<template><div class="art-full-height"><ElCard><ElTable v-loading="loading" :data="rows"><ElTableColumn prop="after_sale_no" label="售后单号" min-width="190"/><ElTableColumn prop="order_no" label="订单号" min-width="190"/><ElTableColumn prop="customer_name" label="用户" width="120"/><ElTableColumn prop="player_name" label="陪玩师" width="120"/><ElTableColumn prop="reason_type" label="原因" width="130"/><ElTableColumn prop="description" label="问题说明" min-width="200" show-overflow-tooltip/><ElTableColumn prop="after_sale_status" label="状态" width="100"/><ElTableColumn label="操作" width="90"><template #default="{row}"><ElButton link type="primary" @click="open(row)">处理</ElButton></template></ElTableColumn></ElTable></ElCard><ElDrawer v-model="visible" title="售后处理" size="620px"><template v-if="detail"><ElDescriptions :column="2" border><ElDescriptionsItem label="售后单号">{{detail.after_sale_no}}</ElDescriptionsItem><ElDescriptionsItem label="订单号">{{detail.order_no}}</ElDescriptionsItem><ElDescriptionsItem label="用户">{{detail.customer_name}}</ElDescriptionsItem><ElDescriptionsItem label="陪玩师">{{detail.player_name}}</ElDescriptionsItem><ElDescriptionsItem label="问题说明" :span="2">{{detail.description}}</ElDescriptionsItem></ElDescriptions><h4>问题凭证</h4><ElImage v-for="url in detail.proofUrls" :key="url" :src="url" :preview-src-list="detail.proofUrls" class="proof" fit="cover"/><div v-if="['PENDING','PROCESSING'].includes(detail.after_sale_status)" class="mt-5"><ElButton type="primary" @click="handle('RESERVICE')">重新服务</ElButton><ElButton type="danger" @click="handle('REJECT')">驳回申请</ElButton><ElButton type="success" @click="handle('CLOSE')">协商完成并关闭</ElButton></div></template></ElDrawer></div></template><script setup lang="ts">import{fetchAfterSales,fetchAfterSale,handleAfterSale}from'@/api/business-manage';const loading=ref(false),rows=ref<any[]>([]),visible=ref(false),detail=ref<any>();async function load(){loading.value=true;try{const d=await fetchAfterSales({current:1,size:100});rows.value=d.records}finally{loading.value=false}}async function open(r:any){detail.value=await fetchAfterSale(r.id);visible.value=true}async function handle(result:string){const remark=await ElMessageBox.prompt('请输入处理说明','处理售后',{inputValidator:v=>Boolean(v)||'请输入处理说明'}).then(x=>x.value);await handleAfterSale(detail.value.id,result,remark);ElMessage.success('处理成功');visible.value=false;load()}onMounted(load)</script><style scoped>.proof{width:120px;height:120px;margin:0 12px 12px 0;border-radius:8px}</style>
